import React, { useState } from 'react';

function LoginPage({ onLogin }) {
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');
    setIsSubmitting(true);

    try {
      const response = await fetch('https://api.azkopos.com/AzkoAPI/GetTenantConnString', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ Pin: pin.trim() }),
      });
      const responseText = await response.text();

      if (responseText.trim().toLowerCase() === 'pin not found') {
        setError('Pin not found');
        return;
      }

      if (!response.ok) {
        throw new Error('Unable to verify PIN. Please try again.');
      }

      const tenant = JSON.parse(responseText);
      if (!tenant || tenant.tenantID == null || !tenant.connString) {
        throw new Error('Unable to verify PIN. Please try again.');
      }

      onLogin();
    } catch (requestError) {
      setError(requestError.message || 'Unable to verify PIN. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="login-page">
      <header className="login-header">
        <div className="login-header-content">Welcome To AzkoPOS</div>
      </header>

      <div className="main-panel login-main-panel">
        <div className="content-wrapper login-content-wrapper">
          <div className="page-header flex-wrap">
            <h3 className="mb-0">Login Form</h3>
          </div>
          <div className="row">
            <div className="card" style={{ width: '100%' }}>
              <div className="card-body">
                <form onSubmit={handleSubmit}>
                  {error && <div className="form-group text-danger" role="alert">{error}</div>}

                  <div className="form-group">
                    <label htmlFor="txtPin">PIN *</label>
                    <input
                      id="txtPin"
                      className="form-control"
                      type="password"
                      placeholder="PIN"
                      value={pin}
                      onChange={(event) => setPin(event.target.value)}
                      required
                    />
                  </div>

                  <button type="submit" className="btn btn-primary mr-2" disabled={isSubmitting}>
                    {isSubmitting ? 'Logging in...' : 'Login'}
                  </button>
                  <button type="button" className="btn btn-danger" onClick={() => setPin('')} disabled={isSubmitting}>
                    Cancel
                  </button>
                </form>
              </div>
            </div>
          </div>
        </div>

        <footer className="footer">
          <div className="d-sm-flex justify-content-center justify-content-sm-between">
            <span className="text-muted d-block text-center text-sm-left d-sm-inline-block">
              Copyright © AzkoIT 2025
            </span>
            <span className="float-none float-sm-right d-block mt-1 mt-sm-0 text-center">
              &nbsp;
            </span>
          </div>
        </footer>
      </div>
    </div>
  );
}

export default LoginPage;
